cat > tests/ScheduledPosts.test.ts <<'E'
import { beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { TestApp } from '@guren/testing'
import app from '../src/app.js'
import { resetDatabase } from '../config/database.js'
import { Post } from '../src/../app/Models/Post.js'
import { User } from '../app/Models/User.js'

describe('scheduled posts', () => {
  let http: TestApp
  let author: any
  let other: any

  beforeAll(async () => {
    http = await TestApp.fromApp(app)
  })

  beforeEach(async () => {
    await resetDatabase()
    author = await User.forceCreate({ name: 'A', email: 'a@x.test', passwordHash: 'x' })
    other = await User.forceCreate({ name: 'B', email: 'b@x.test', passwordHash: 'x' })
  })

  it('hides a scheduled post from everyone but its author', async () => {
    const post = await Post.forceCreate({
      title: 'Soon', excerpt: 'e', body: 'b', authorId: author.id, publishedAt: '2999-01-01T00:00:00.000Z',
    })
    await http.get(`/posts/${post.id}`).assertNotFound()
    await http.actingAs(other).get(`/posts/${post.id}`).assertNotFound()
    await http.actingAs(author).get(`/posts/${post.id}`).assertOk()
    const guestSearch = await http.query('/posts/search', { keywords: ['Soon'] })
    expect((await guestSearch.json<any>()).data).toHaveLength(0)

    await Post.forceUpdate({ id: post.id }, { publishedAt: '2000-01-01T00:00:00.000Z' })
    await http.get(`/posts/${post.id}`).assertOk()
  })

  it('rejects an invalid publishAt', async () => {
    const csrf = await http.actingAs(author).withCsrf()
    await csrf.json().post('/posts', { title: 't', excerpt: 'e', body: 'b', publishAt: 'next tuesday' }).assertUnprocessable()
  })

  it('lists scheduled posts from the console', async () => {
    await Post.forceCreate({ title: 'Later', excerpt: 'e', body: 'b', authorId: author.id, publishedAt: '2999-01-01T00:00:00.000Z' })
    await Post.forceCreate({ title: 'Past', excerpt: 'e', body: 'b', authorId: author.id, publishedAt: '2000-01-01T00:00:00.000Z' })
    const proc = Bun.spawnSync(['bun', 'bin/console.ts', 'posts:scheduled'], { env: { ...process.env, NODE_ENV: 'test' } })
    expect(proc.exitCode).toBe(0)
    expect(proc.stdout.toString()).toBe('1\tLater\t2999-01-01T00:00:00.000Z\n')
  })
})
E
sed -i "s#'../src/../app/Models/Post.js'#'../app/Models/Post.js'#" tests/ScheduledPosts.test.ts
bun run typecheck 2>&1 | tail; bun test 2>&1 | tail -30
